<!--
  Ficheiro: src/components/live/ChannelEditDialog.vue
  Tipo: Formulário modal Vue.
  Função: Edita canais_tv com validação acessível, duplicados e upload de logótipo.
-->
<script setup lang="ts">
import { computed,nextTick,ref,watch } from "vue";import LookupMultiSelect from "./LookupMultiSelect.vue";import { channelRepository } from "@/domain/repositories";import type { ChannelRecord,NamedRecord,TvCategoryRecord } from "@/types/records";import { channelToForm,hasErrors,validateChannelForm,type ChannelFormErrors } from "@/domain/live/validation";import { checkChannelDuplicate } from "@/domain/live/duplicate";
const props=defineProps<{channel:ChannelRecord|null;countries:NamedRecord[];languages:NamedRecord[];tags:NamedRecord[];categories:TvCategoryRecord[]}>();const emit=defineEmits<{close:[];saved:[ChannelRecord];archived:[string]}>();const form=ref(channelToForm({id:"",created:"",updated:"",nome:"",url_stream:""} as ChannelRecord));const errors=ref<ChannelFormErrors>({});const submitError=ref("");const warning=ref("");const logo=ref<File|null>(null);const removeLogo=ref(false);const saving=ref(false);const errorSummary=ref<HTMLElement|null>(null);const firstInput=ref<HTMLInputElement|null>(null);const errorEntries=computed(()=>Object.entries(errors.value));
watch(()=>props.channel,async c=>{if(c){form.value=channelToForm(c);errors.value={};submitError.value="";warning.value="";logo.value=null;removeLogo.value=false;await nextTick();firstInput.value?.focus()}},{immediate:true});
function described(field: keyof ChannelFormErrors, hasHint = true): string | undefined {
  const ids: string[] = [];
  if (hasHint) ids.push(`${field}-hint`);
  if (errors.value[field]) ids.push(`${field}-error`);
  return ids.length ? ids.join(" ") : undefined;
}
async function focusErrors(){await nextTick();errorSummary.value?.focus();const key=Object.keys(errors.value)[0];document.getElementById(`channel-${key}`)?.focus()}
function chooseLogo(e:Event){logo.value=(e.target as HTMLInputElement).files?.[0]||null;errors.value={...errors.value,...validateChannelForm(form.value,logo.value)};if(logo.value)removeLogo.value=false}
async function save(): Promise<void> {
  const validationErrors = validateChannelForm(form.value, logo.value);
  errors.value = validationErrors;
  submitError.value = "";
  warning.value = "";
  await nextTick();
  if (hasErrors(validationErrors)) { await focusErrors(); return; }
  if (!props.channel) { submitError.value = "Não foi possível identificar o canal a editar."; return; }
  saving.value = true;
  try {
    const duplicate = await checkChannelDuplicate({ id: props.channel.id, tvg_id: form.value.tvg_id, url_stream: form.value.url_stream, nome: form.value.nome, pais: form.value.pais });
    if (duplicate.blocked) { submitError.value = duplicate.message; return; }
    warning.value = duplicate.warning ? duplicate.message : "";
    const payload: Record<string, unknown> = { ...form.value, nome: form.value.nome.trim(), url_stream: form.value.url_stream.trim(), url_pagina: form.value.url_pagina.trim(), tvg_logo_url: form.value.tvg_logo_url.trim(), tvg_id: form.value.tvg_id.trim(), tvg_name: form.value.tvg_name.trim(), epg_id: form.value.epg_id.trim(), playlist_origem: form.value.playlist_origem.trim() };
    if (logo.value) payload.logo = logo.value; else if (removeLogo.value) payload.logo = null;
    emit("saved", await channelRepository.update(props.channel.id, payload) as ChannelRecord);
  } catch (cause) { submitError.value = cause instanceof Error ? cause.message : String(cause); }
  finally { saving.value = false; }
}
async function archive(){if(!props.channel||!confirm(`Arquivar “${props.channel.nome}”?\n\nOs links associados não serão eliminados.`))return;saving.value=true;try{await channelRepository.update(props.channel.id,{cemiterio:true});emit("archived",props.channel.id)}catch(c){submitError.value=c instanceof Error?c.message:String(c)}finally{saving.value=false}}
</script>
<template><Teleport to="body"><div v-if="channel" class="dialog-backdrop" @click.self="!saving&&emit('close')"><section class="dialog-panel channel-edit" role="dialog" aria-modal="true" aria-labelledby="channel-edit-title" @keydown.esc.prevent="!saving&&emit('close')"><form class="channel-edit-form" novalidate @submit.prevent="save"><div class="dialog-header"><div><p class="eyebrow">Gestão TV</p><h2 id="channel-edit-title">Editar canal</h2></div><button class="icon-button" type="button" aria-label="Fechar" :disabled="saving" @click="emit('close')">×</button></div><div v-if="errorEntries.length" ref="errorSummary" class="form-error-summary" role="alert" aria-live="assertive" tabindex="-1"><h3>Não foi possível guardar</h3><p>Corrige {{errorEntries.length}} {{errorEntries.length===1?'campo':'campos'}}.</p><ul><li v-for="[field,message] in errorEntries" :key="field"><button type="button" @click="document.getElementById(`channel-${field}`)?.focus()">{{message}}</button></li></ul></div><div v-if="submitError" class="form-alert form-alert-error" role="alert">{{submitError}}</div><p v-if="warning" class="field-warning" role="status">{{warning}}</p><div class="form-grid"><label class="form-field field-wide"><span>Nome *</span><input id="channel-nome" ref="firstInput" v-model="form.nome" maxlength="200" :aria-invalid="errors.nome ? 'true' : 'false'" :aria-describedby="described('nome')"/><small id="nome-hint" class="field-hint">Máximo de 200 caracteres.</small><small v-if="errors.nome" id="nome-error" class="field-error" role="alert">{{errors.nome}}</small></label><label class="form-field field-wide"><span>Stream principal *</span><input id="channel-url_stream" v-model="form.url_stream" :aria-invalid="errors.url_stream ? 'true' : 'false'" :aria-describedby="described('url_stream')"/><small id="url_stream-hint" class="field-hint">HTTP(S), RTMP(S), RTSP, RTP ou UDP.</small><small v-if="errors.url_stream" id="url_stream-error" class="field-error" role="alert">{{errors.url_stream}}</small></label><label class="form-field"><span>País</span><select v-model="form.pais"><option value="">Sem país</option><option v-for="x in countries" :key="x.id" :value="x.id">{{x.nome}}</option></select></label><label class="form-field"><span>Categoria</span><select v-model="form.categoria"><option value="">Sem categoria</option><option v-for="x in categories" :key="x.id" :value="x.id">{{x.nome}}</option></select></label><label class="form-field"><span>Qualidade</span><select v-model="form.qualidade"><option>Desconhecida</option><option>SD</option><option>HD</option><option value="FHD">Full HD</option><option>4K</option></select></label><label class="form-field"><span>Ordem</span><input id="channel-ordem" v-model.number="form.ordem" type="number" min="0" step="0.1"/><small v-if="errors.ordem" id="ordem-error" class="field-error" role="alert">{{errors.ordem}}</small></label><label class="form-field field-wide"><span>Página oficial</span><input id="channel-url_pagina" v-model="form.url_pagina" type="url"/><small v-if="errors.url_pagina" id="url_pagina-error" class="field-error" role="alert">{{errors.url_pagina}}</small></label><label class="form-field field-wide"><span>URL do logótipo IPTV</span><input id="channel-tvg_logo_url" v-model="form.tvg_logo_url" type="url"/><small v-if="errors.tvg_logo_url" id="tvg_logo_url-error" class="field-error" role="alert">{{errors.tvg_logo_url}}</small></label><label class="form-field"><span>Logótipo local</span><input id="channel-logo" type="file" accept="image/jpeg,image/png,image/webp,image/avif" @change="chooseLogo"/><small v-if="errors.logo" id="logo-error" class="field-error" role="alert">{{errors.logo}}</small></label><label v-if="channel.logo" class="check-field"><input v-model="removeLogo" type="checkbox" :disabled="!!logo"/> Remover logótipo local</label><LookupMultiSelect id="channel-languages" v-model="form.idiomas" label="Idiomas" :options="languages" :max="10"/><LookupMultiSelect id="channel-tags" v-model="form.tags" label="Tags" :options="tags" :max="10"/></div><details class="detail-section"><summary>Dados técnicos IPTV/XMLTV</summary><div class="form-grid"><label class="form-field"><span>TVG-ID</span><input id="channel-tvg_id" v-model="form.tvg_id" maxlength="200"/></label><label class="form-field"><span>TVG name</span><input id="channel-tvg_name" v-model="form.tvg_name" maxlength="300"/></label><label class="form-field"><span>EPG-ID</span><input id="channel-epg_id" v-model="form.epg_id" maxlength="200"/></label><label class="form-field"><span>Playlist de origem</span><input id="channel-playlist_origem" v-model="form.playlist_origem" maxlength="500"/></label></div></details><div class="channel-state-options"><label class="check-field"><input v-model="form.favorito" type="checkbox"/> Favorito</label><label class="check-field"><input v-model="form.ativo" type="checkbox"/> Ativo</label><label class="check-field"><input v-model="form.adulto" type="checkbox"/> Conteúdo adulto</label></div><div class="form-actions"><button class="button button-danger" type="button" :disabled="saving" @click="archive">Arquivar</button><button class="button button-secondary" type="button" :disabled="saving" @click="emit('close')">Cancelar</button><button class="button button-primary" type="submit" :disabled="saving" :aria-busy="saving">{{saving?'A guardar…':'Guardar alterações'}}</button></div><p class="sr-only" aria-live="polite">{{saving?'A guardar o canal.':''}}</p></form></section></div></Teleport></template>
